import {LINES,SYMBOLS,CONFIG,MODES} from './config.js';
export function weighted(values,weights,rng=Math.random){let n=rng()*weights.reduce((a,b)=>a+b,0);return values.find((_,i)=>(n-=weights[i])<0)??values.at(-1)}
export function regular(rng=Math.random){return {id:weighted(SYMBOLS.map(s=>s.id),SYMBOLS.map(s=>s.weight),rng)}}
export function makeGrid(wager,modes=[],rng=Math.random){const grid=Array.from({length:5},()=>Array.from({length:4},()=>regular(rng)));for(let c=0;c<4;c++)for(let r=0;r<4;r++){if(rng()<CONFIG.invoiceChance)grid[c][r]={id:'invoice',value:Math.round(wager*weighted(CONFIG.cashMultiples,CONFIG.cashWeights,rng))};else if(modes.includes('pop')&&rng()<.045)grid[c][r]={id:'effect',mult:weighted([2,3,5],[7,2,1],rng)};}
for(const [id,m] of Object.entries(MODES))if(rng()<CONFIG.pinChance)grid[m.reel][Math.floor(rng()*4)]={id:'pin',mode:id};
if(modes.includes('tiny')||rng()<CONFIG.collectorChance){const enhanced=rng()<(modes.includes('logo')?.75:.22);grid[4][Math.floor(rng()*4)]={id:enhanced?'rush':'collect',mult:enhanced?weighted(modes.includes('logo')?[2,3,5,10]:[1,2,3,5,10],[50,28,14,6,2].slice(modes.includes('logo')?1:0),rng):1};}return grid;}
export function lineWins(grid,wager){const wins=[];LINES.forEach((rows,line)=>{const ids=rows.map((r,c)=>grid[c][r].id);let best=null;for(const s of SYMBOLS){let count=0;while(count<5&&(ids[count]===s.id||ids[count]==='wild'))count++;if(count>=3){const amount=Math.round(wager*s.pay[count-3]/20);if(!best||amount>best.amount)best={line,rows,count,id:s.id,amount};}}if(best)wins.push(best)});return wins}
export function collection(grid){const invoices=[],collectors=[],effects=[];grid.forEach((col,c)=>col.forEach((s,r)=>{if(s.id==='invoice')invoices.push({c,r,...s});if(c===4&&['collect','rush'].includes(s.id))collectors.push({c,r,...s});if(s.id==='effect')effects.push({c,r,...s});}));const subtotal=invoices.reduce((a,s)=>a+s.value,0),effectMultiplier=effects.reduce((a,s)=>a*s.mult,1);return {invoices,collectors,effects,subtotal,effectMultiplier,amount:collectors.reduce((a,s)=>a+subtotal*s.mult*effectMultiplier,0)}}
export function triggered(grid,rng=Math.random){const pins=[...new Set(grid.flat().filter(s=>s.id==='pin').map(s=>s.mode))];return pins.length===3?pins:pins.filter(()=>rng()<CONFIG.activationChance)}
